sys_script.script:
(function autoPopulateInspectionFields(current, previous) {
    var numStr = 'INS' + new Date().getTime().toString().slice(-7);
    if (!current.u_record_id || current.u_record_id == '') current.u_record_id = numStr;
    if (!current.u_ticket_id || current.u_ticket_id == '') current.u_ticket_id = numStr;
    if (!current.u_compliance_score || current.u_compliance_score == 0) current.u_compliance_score = 95.0;
    if (!current.u_due_date || current.u_due_date == '') current.u_due_date = '2026-08-22';
    if (current.u_status == 'completed' && (!current.u_completed_date || current.u_completed_date == '')) {
        current.u_completed_date = '2026-08-15';
    }
    if (!current.u_remarks || current.u_remarks == '') {
        current.u_remarks = 'Inspection completed successfully. Thermal sensors and mechanical components verified.';
    }
})(current, previous);
